F = ["id", "area", "level", "input", "pre", "steps", "expected", "evidence", "sev", "source", "status", "notes"]
T = [tuple(u.get(k, v) for k, v in zip(F, t)) if (u := UPD.get(t[0])) else t for t in T]

AREAS = ["Import", "Garis potong", "Nesting", "Edit layout", "Export", "Operator/hardware", "Kinerja"]
md = []
for area in AREAS:
    md.append(f"### {area}\n")
    md.append("| ID | Tingkat | Input | Langkah | Hasil benar | Bukti | Sumber | Status |")
    md.append("| --- | --- | --- | --- | --- | --- | --- | --- |")
    for t in (t for t in T if t[1] == area):
        st = t[10] + (f" — {t[11]}" if t[11] else "")
        md.append("| " + " | ".join(c.replace("|", "\\|") for c in (t[0], t[2], t[3], t[5], t[6], t[7], t[9], st)) + " |")
    md.append("")
tpl = open(TPL, encoding="utf-8").read()
counts = {s: sum(t[10] == s for t in T) for s in ("PASS", "FAIL", "BLOCKED", "NOT RUN")}
tpl = tpl.replace("{{TESTCASES}}", "\n".join(md).rstrip()).replace("{{TOTAL}}", str(len(T)))
for s, n in counts.items():
    tpl = tpl.replace("{{" + s.replace(" ", "_") + "}}", str(n))
open(OUT_MD, "w", encoding="utf-8", newline="\n").write(tpl)
